  "privRetention": "Conservazione e cancellazione",
  "privRights": "I tuoi diritti",
  "noticeReopen": "Avviso sull’archiviazione",
  "noticeLabel": "Avviso sull’archiviazione del browser",
  "noticeText": "Cook usa l’archiviazione del browser per le funzioni di cucina e di accesso che usi. Non viene aggiunta alcuna archiviazione pubblicitaria o analitica.",
  "noticeClose": "Chiudi avviso sull’archiviazione",
  "privDraftLabel": "Bozza — aggiornata il 28 ottobre 2026.",
  "privDraft": "Le funzioni dell’account sono in fase di test. I dati del gestore e dei servizi riportati sotto devono essere completati prima del lancio pubblico.",
  "privWho1": "Cook è gestito da [denominazione legale e indirizzo postale del gestore]. Per domande e richieste sulla privacy scrivi a [indirizzo email per la privacy]. Questi dati devono essere completati prima dell’apertura delle registrazioni.",
  "privWhat1": "Quando crei un account, usiamo la tua email, un identificativo dell’account, i dati di autenticazione con password e lo stato di verifica per fornire e proteggere il tuo account. Le password sono gestite dal fornitore di autenticazione come hash sicuri; Cook non conserva password leggibili. Salviamo la disposizione della cucina, la lingua scelta, il tema e le unità di misura per ripristinare le impostazioni su tutti i dispositivi. Email e password sono necessarie per avere un account; puoi consultare le ricette anche senza.",
  "privWhat2": "Il trattamento dei dati dell’account e delle impostazioni è necessario per fornire il servizio di account che richiedi (art. 6, par. 1, lett. b) del GDPR). Dati limitati di sicurezza e prevenzione degli abusi possono essere trattati sulla base del legittimo interesse (art. 6, par. 1, lett. f)), nei limiti della necessità e del bilanciamento. Le email di verifica e di reimpostazione della password sono messaggi di servizio, non marketing. La funzione account non aggiunge pubblicità né analisi.",
  "privStorage1": "Cook usa sessionStorage per portare la tua cucina, l’avanzamento della ricetta e le tue scelte tra le pagine della stessa scheda. Quando hai effettuato l’accesso, contiene anche la tua sessione di autenticazione. Di norma il browser lo cancella alla fine della sessione della scheda, ma il ripristino delle sessioni del browser può conservarlo. L’uscita dall’account cancella i dati di scheda di Cook. La chiusura dell’avviso sull’archiviazione resta solo in quella scheda. Gli script di Cook non impostano cookie. I tuoi fornitori di hosting o di servizi possono effettuare trattamenti di sicurezza propri, che devono essere documentati prima del lancio.",
  "privStorage2": "OK e il pulsante di chiusura dell’avviso sull’archiviazione chiudono soltanto l’avviso. Non autorizzano analisi, pubblicità né altri tracciamenti facoltativi. Qualsiasi futura archiviazione non essenziale richiederà una scelta separata prima di iniziare, con un rifiuto e una revoca altrettanto semplici.",
  "privOther1": "L’attuale funzione vocale dell’elenco ricette chiede a country.is un paese approssimativo in base al tuo indirizzo IP per scegliere la lingua vocale. Se usi il riconoscimento tramite microfono, il browser può inviare l’audio al suo fornitore di riconoscimento vocale. In alternativa puoi digitare gli ingredienti. Questi fornitori, le loro politiche e la base giuridica di queste funzioni devono essere verificati prima del lancio pubblico.",
  "privProviders1": "Fornitore di account previsto: Supabase (PostgreSQL e autenticazione gestiti), con una regione del database selezionata nell’UE. Fornitore email: [fornitore]. Hosting del sito: [fornitore]. Il gestore deve confermare i fornitori effettivi, gli accordi sul trattamento, i sub-responsabili, la posizione dei log ed eventuali trasferimenti fuori dal SEE. Una regione del database nell’UE non esclude di per sé i trasferimenti internazionali. Se pertinente, indica la decisione di adeguatezza o le garanzie contrattuali applicabili e come ottenerne una copia.",
  "privRetention1": "Le impostazioni dell’account sono conservate finché l’account è attivo. Puoi chiederne la cancellazione tramite il contatto privacy indicato sopra. Prima del lancio il gestore deve specificare la procedura di risposta alle richieste di cancellazione, la scadenza degli account non verificati e i periodi di conservazione dei log di sicurezza e dei backup. I dati cancellati possono restare in backup ad accesso limitato fino alla fine del periodo di conservazione documentato.",
  "privRights1": "A seconda delle condizioni applicabili, puoi chiedere accesso, rettifica, cancellazione, limitazione o portabilità, oppure opporti al trattamento basato sul legittimo interesse. Contatta il gestore indicato sopra; di norma le richieste ricevono risposta entro un mese, motivando eventuali proroghe previste dalla legge. Puoi presentare reclamo all’autorità di controllo, tra cui la NAIH ungherese su naih.hu. Cook non usa le impostazioni dell’account per decisioni automatizzate con effetti giuridici o effetti analogamente significativi.",
